![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

If `rightsStatus` is an unrecognized or unallowed status (e.g., `'rights_pending'`), `rightsStatusReasonCode` currently returns an empty string `''`. This results in `rightsDisplayGate.reasonCodes` being empty even though the display is blocked. To ensure robust fail-closed behavior with clear diagnostics, return `'rights_display_blocked'` as a fallback for any unallowed status.

```javascript
function rightsStatusReasonCode(rightsStatus) {
  if (!rightsStatus) return 'rights_status_missing';
  if (rightsStatus.includes('unmodeled')) return 'rights_policy_unmodeled';
  if (rightsStatus.includes('review_required')) return 'rights_review_required';
  if (rightsStatus.includes('link_only')) return 'rights_link_only';
  if (rightsStatus.includes('citation_only')) return 'rights_citation_only';
  if (rightsStatus.includes('excerpt_only')) return 'rights_excerpt_only';
  if (
    rightsStatus.includes('blocked')
    || rightsStatus.includes('denied')
    || rightsStatus.includes('not_allowed')
  ) {
    return 'rights_display_blocked';
  }
  if (rightsStatus === 'rights_display_allowed' || rightsStatus === 'rights_not_required') {
    return '';
  }
  return 'rights_display_blocked';
}
```

